"""English edition at /eng. Shares the Russian edition's visual assets."""
from pathlib import Path
from html import escape

PAGES = [('index','Home'),('why','Why SAFEBOX'),('about','About the project'),('how-it-works','How it works'),('products','Products & contents'),('choose','Choose your kit'),('assistant','AI assistant'),('partners','Partners & distributors'),('faq','FAQ'),('stories','Stories & feedback'),('kids','Caring for children'),('contacts','Contact'),('qr-library','QR library'),('video-library','Video library'),('printed-guide','Printed guide'),('free-guide','Free digital guide')]

def btn(label, url, primary=False):
 return f'<a class="btn{" primary" if primary else ""}" href="{url}">{label} ↗</a>'
def sec(body, kind=''):
 return f'<section class="section {kind}"><div class="wrap">{body}</div></section>'
def head(label,title,desc=''):
 return f'<div class="section-head"><div><div class="eyebrow">{label}</div><h2>{title}</h2></div><p class="muted">{desc}</p></div>'
def intro(label,title,desc):
 return f'<div class="wrap page-head"><div class="eyebrow">{label}</div><h1>{title}</h1><p class="lead">{desc}</p></div>'
def cards(items):
 return '<div class="grid">'+''.join(f'<article class="card"><span class="num">0{i+1} / SAFEBOX</span><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate(items))+'</div>'
def faq(items):
 return '<div class="faq-group">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'

WIFE = sec(head('01 / An honest beginning', 'I never planned to build a first-aid kit.<br>Until my wife needed one.', 'The personal experience behind SAFEBOX.')+'''<div class="founder-grid"><div class="story-aside"><span class="story-time">3<span>minutes</span></span><p>According to the founder, his wife’s condition deteriorated within just a few minutes.</p><div class="story-photo" role="img" aria-label="Illustration from the project concept"><img src="assets/family.png" alt="Family beside a SAFEBOX concept" loading="lazy"></div><p class="small">Project illustration, not a photograph of the incident.</p></div><div class="story-copy"><p class="story-opening">“My wife became unwell right in my arms. Her limbs and mouth cramped, she had spasms, and breathing became difficult. It all happened in about three minutes.”</p><p>“I associated it with severe dehydration. We had Zyrtec at home; I gave it to her, and she felt better afterwards. That is how I experienced and remember that moment.”</p><p>That experience made me realise how important it is to have the right supplies within reach. But putting medicines in a box is not enough. You need to know where everything is, read the labels, and find the information you need.</p><p>Even after that incident, I did not immediately organise our home medicine kit. The danger passes, and you put it off again.</p><p>That is how SAFEBOX began: organised storage, visible sections, large labels, a guide and a QR entry point. A system that the whole family can understand.</p><aside class="notice small">This is a personal recollection, not treatment guidance. The cause of the episode and any link between improvement and the medicine have not been established. An emergency requires professional medical help.</aside></div></div>''','founder-section')
CHILD = sec('''<div class="child-story-grid"><div class="story-night"><span class="eyebrow">Another story from our family</span><span class="night-label">At night. At home. Suddenly.</span><blockquote>“Dad,<br>I can’t<br><em>breathe.”</em></blockquote><span>Words you never forget.</span></div><article class="story-copy"><span class="badge">The founder’s personal experience</span><h2>What if we had<br>nothing at home?</h2><p>“One night, my son suddenly started coughing, without stopping. Then he said: ‘Dad, I can’t breathe.’ He was coughing so hard it felt as though he would cough his lungs out.</p><p>Luckily, we already had a nebuliser and Pulmicort at home. We had bought them three years earlier on a doctor’s advice. What if we hadn’t?”</p><p>The founder describes this as an episode of croup. It is another reason behind SAFEBOX: discuss the supplies your family may need with a doctor in advance, know where they are, and keep individual instructions close by.</p><aside class="notice small">A personal account, not a confirmed diagnosis or a recommendation to use this medicine. An old purchase does not mean a medicine is still suitable: check expiry dates and storage requirements, and follow current medical advice. Severe breathing difficulty requires emergency help. <a href="https://www.nhs.uk/conditions/croup/" target="_blank" rel="noopener noreferrer">Warning signs: NHS ↗</a>. Use your local emergency number; in Russia, 112 or 103.</aside></article></div>''','child-story')

RESOURCE_ITEMS = [('qr-library','▦','QR library','Scan. Open.<br>Learn.','QR codes for recognised educational resources, ready to save or print.'),('video-library','▷','Video library','See it.<br>Understand it.','First-aid videos and professional explanations to explore in advance.'),('printed-guide','▤','Printed guide','Important information.<br>On paper.','Our planned printed edition and a free preparation sheet available today.'),('assistant','✳','AI assistant','What belongs at home.<br>And why.','An explainable AI concept. Today, use the question builder to prepare for a medical consultation.')]
def resources():
 return sec(head('Knowledge beside your kit','More than storage.<br>Know where to find an answer.')+'<div class="resource-grid">'+''.join(f'<a class="resource-card" href="{slug}.html"><span class="resource-symbol" aria-hidden="true">{icon}</span><span class="num">{name}</span><h3>{title}</h3><p>{desc}</p><b>Explore ↗</b></a>' for slug,icon,name,title,desc in RESOURCE_ITEMS)+'</div>','resources-section')
def choices():
 return sec(head('Start with your household','Who are you preparing for?')+'''<div class="grid two"><a class="card choice" href="choose.html?kit=adult"><span class="num">01 / ONE OR TWO ADULTS</span><h3>Adult kit</h3><p>Organise supplies for yourself and another adult. Include individual prescriptions.</p><img class="english-kit" src="assets/box.png" alt="SAFEBOX case concept" loading="lazy"><b>Choose →</b></a><a class="card choice" href="choose.html?kit=family"><span class="num">02 / ADULTS AND CHILDREN</span><h3>Family kit</h3><p>Separate adult and children’s supplies. Prepare questions for your paediatrician.</p><img class="english-kit" src="assets/box.png" alt="SAFEBOX family case concept" loading="lazy"><b>Choose →</b></a></div>''')
def steps():
 return sec(head('A simple path','From intention to an organised kit.')+cards([('Choose','Adult or family: start with a simple choice, without a long questionnaire.'),('Discuss','Agree on your supplies and individual prescriptions with a healthcare professional.'),('Organise','Obtain agreed supplies, label the sections and show your family where to find them.')]))
FAQ = [('Is SAFEBOX a medicine or a storage system?','SAFEBOX is a concept for organising medicines and related information. Medicines are selected individually with a healthcare professional and purchased separately.'),('Is it suitable for someone without medical training?','The navigation is designed to make storage easier to understand. It does not replace first-aid training, a diagnosis or professional medical help.'),('Can I buy it and order medicines in one click?','Sales, payments and pharmacy ordering are not connected yet. The current site helps you explore the concept and prepare a checklist.'),('What if there is no phone or internet?','The concept includes printed information. Online videos and QR resources need an internet connection. Keep your individual prescriptions and key contacts available offline.'),('Does the AI assistant prescribe medicines?','No. The live tool is a local question builder, not an AI model. The proposed AI module would explain suggestions for a doctor to review.'),('Are the pictures photographs of a finished product?','Product images are concept visuals. Labels and QR-like markings inside the images are not medical instructions or working codes.'),('Are there verified customer reviews?','There are no published, verified product reviews yet. Founder stories describe personal experiences, not evidence of product effectiveness.')]

def contact_form(partner=False):
 extra = '<label class="field">Company<input name="company" maxlength="150" required></label><label class="field">Region<input name="region" maxlength="100" required></label>' if partner else ''
 options = ['Retail','Distribution','Pharmacy network','Corporate purchasing','Other'] if partner else ['Product question','Purchase and launch','Feedback or testing','Caring for children','Other']
 return f'''<form class="form english-draft"><div class="notice">Online submission is not connected. This form downloads a draft to your device; it does not send a message.</div><label class="field">Your name<input name="name" autocomplete="name" maxlength="100" required></label>{extra}<label class="field">Subject<select name="subject">{''.join('<option>'+x+'</option>' for x in options)}</select></label><label class="field">Reply email<input name="email" type="email" autocomplete="email" maxlength="150" required></label><label class="field">Message<textarea name="message" maxlength="3000" required placeholder="Please do not include medical information."></textarea></label><button class="btn primary" type="submit">Download enquiry draft ↓</button><p class="small muted">Your entries are not saved in the browser. The downloaded file contains the details you entered.</p><p class="form-status" role="status"></p></form>'''

def make_content():
 c={}
 c['index']='''<section class="hero home-hero line-pattern"><div class="wrap"><div class="hero-grid"><div><div class="eyebrow">SAFEBOX / Ready for the first moments</div><h1>A reliable system<br>to <span>store and find</span><br>medicines.</h1><p class="lead">A quick response in an emergency can make a difference to someone you love.</p><p class="hero-explain">Prepare in advance: know what you have, where it is, and where to find the instructions.</p><div class="reference-icons"><div><span class="resource-symbol">▦</span><span>Colour-coded<br>navigation</span></div><div><span class="resource-symbol">⌕</span><span>Resources<br>on your phone</span></div><div><span class="resource-symbol">▤</span><span>Printed<br>information</span></div><div><span class="resource-symbol">+</span><span>A clear<br>structure</span></div></div><div class="actions">'''+btn('Build your system','choose.html',True)+btn('Our story','#founder-story')+'''</div><p class="mini-note">For your home and loved ones · Product concept · Preparing for launch</p></div><div class="reference-hero-scene"><img src="assets/family.png" alt="Illustration of a family with a SAFEBOX concept and a printed guide" fetchpriority="high"></div></div><div class="features-strip"><div><b>Store clearly</b>A place for every item</div><div><b>Find more easily</b>Colour, text and symbols</div><div><b>Prepare in advance</b>A checklist and regular reviews</div><div><b>Care for your family</b>A system everyone can understand</div></div></div></section>'''
 c['index']+=WIFE.replace('class="section founder-section"','class="section founder-section" id="founder-story"')+CHILD
 c['index']+=sec(head('02 / The people closest to you','The person who needs help<br>may be someone you love.')+cards([('Your partner','The person beside you every day.'),('Your child','Preparation begins before a frightening night.'),('Your parents','Make the location of supplies and instructions clear.')])+'<div class="notice">The founder’s perspective: when a loved one’s safety is at stake, even 10,000–20,000 roubles can feel secondary. This is a reflection on preparedness, not a product price or a promise of an outcome.</div>','care-section line-pattern')
 c['index']+=sec(head('03 / Compare the approach','A container for medicines.<br>Or an organised system.')+'''<div class="grid two"><article class="card"><span class="num">CONVENTIONAL STORAGE</span><h3>A box is a starting point</h3><img class="english-product" src="assets/gallery/standard-case.jpg" alt="Example of a conventional medicine case" loading="lazy"><p>You create the layout, organise the instructions and keep track of supplies yourself.</p></article><article class="card"><span class="num">SAFEBOX CONCEPT</span><h3>Storage, labels and information</h3><img class="english-product" src="assets/gallery/open-kit.png" alt="Open SAFEBOX concept with coloured sections" loading="lazy"><p>Visible sections, large labels and a shared structure across the case, printed materials and digital resources.</p></article></div>''','compare-section')
 c['index']+=sec(head('04 / The project in one view','Preparedness you can see.','Original project presentation, in Russian.')+'<img class="english-slide" src="assets/gallery/presentation-08.jpg" alt="Original Russian-language project slide illustrating the SAFEBOX concept" loading="lazy">','presentation-section')+resources()
 c['index']+=sec(head('The need','Less searching.<br>More clarity.')+cards([('Know what is available','Keep an up-to-date inventory instead of relying on memory.'),('Know where it belongs','Make the layout clear to other adults in your household.'),('Know where to look','Keep individual instructions and reliable learning resources accessible.')]))
 c['index']+=sec(head('Inside the concept','A place for every item.')+'<div class="split"><img class="english-product" src="assets/gallery/open-kit.png" alt="Open storage concept" loading="lazy"><div><h3>Colour, text and symbols together</h3><p>Sections support navigation. They do not diagnose symptoms or determine which medicine to use.</p>'+btn('Explore the system','how-it-works.html')+'</div></div>','tinted')
 c['index']+=sec(head('Product gallery','Explore the formats.','Concept visuals with original Russian labels; not finished retail products.')+'<div class="grid">'+''.join(f'<article class="card"><img class="english-product" src="assets/gallery/{file}" alt="{title} concept" loading="lazy"><h3>{title}</h3></article>' for file,title in [('open-kit.png','The main system'),('compact.png','Compact format'),('fridge.png','Separate cold storage')])+'</div>')+choices()+steps()
 c['index']+=sec(head('Grow with us','A project built around care.')+cards([('Partners and distributors','Help develop retail, pharmacy and distribution channels. <a href="partners.html">Explore partnership →</a>'),('Caring for children','A proposed play-doctor range and a future charitable programme. <a href="kids.html">Read more →</a>'),('Stories and feedback','Explore the founder’s experiences and help shape the system. <a href="stories.html">Read the stories →</a>')]))
 c['index']+=sec(head('Before you choose','Good questions deserve clear answers.')+faq(FAQ[:4]))+sec('<div class="banner"><div><h2>Prepare now.<br>Care ahead.</h2><p>Start by choosing who your kit is for.</p></div>'+btn('Choose your kit','choose.html')+'</div>','compact')
 c['why']=intro('Why SAFEBOX','Confidence starts<br>with preparation.','The goal is simple: know what is at home, where it is stored, and where to find the relevant information.')+sec(cards([('Ready at home','Prepare with a healthcare professional before an urgent situation develops.'),('Clear to the family','A familiar layout helps another adult find the supplies you have agreed to keep.'),('Information close by','Store current individual instructions alongside the right items.')]))+sec(head('A practical distinction','Organisation is part of readiness.')+faq([('What can the system help with?','Storage, labelling, inventory reviews and access to information.'),('What can it not do?','It cannot guarantee an outcome, diagnose an illness, prescribe treatment or replace emergency care.')]))+choices()
 c['about']=intro('About the project','A personal experience.<br>A practical idea.','SAFEBOX grew out of the founder’s wish to make home medicine storage understandable to the whole family.')+WIFE+CHILD+sec(cards([('Our purpose','Make it easier to prepare and keep important information accessible.'),('Our approach','Physical organisation, printed materials and digital access belong together.'),('Current stage','Product concept and preparation tools. Sales and pharmacy integrations are not yet live.')]))
 c['how-it-works']=intro('How it works','A clear structure.<br>At every step.','A physical case, visible labels and accessible information form one system.')+steps()+sec('<div class="split"><img class="english-product" src="assets/gallery/open-kit.png" alt="Open SAFEBOX concept with labelled compartments"><div><h2>Find the section.<br>Read the label.</h2><p>Use colour, symbols and text together. Keep medicines identifiable in their original packaging and retain the manufacturer’s instructions.</p><p>The illustrated sections are a navigation concept, not a treatment algorithm. Individual use follows professional advice.</p></div></div>')+resources()
 c['products']=intro('Products & contents','Choose the format.<br>Agree on the contents.','SAFEBOX is an organisation system. Names, quantities, strengths and doses of medicines must be agreed individually with a healthcare professional.')+choices()+sec(cards([('Guide','A planned information-led format for organising an existing home kit. <a href="printed-guide.html">Printed edition →</a>'),('DIY SAFEBOX','A concept with a case, dividers, large labels and printed materials for self-assembly.'),('Premium SAFEBOX','A rigid-case concept with adjustable sections and a consistent navigation system.')]))+sec(head('Personal contents','No universal medicine list.')+'<div class="notice">There is no clinically validated, universal medicine or dosage list on this site. Product images may contain illustrative labels; do not use them as prescriptions. Final specifications, prices and availability will be announced before launch.</div>'+btn('Prepare questions for your doctor','assistant.html'))
 c['choose']=intro('Choose your kit','Two starting points.<br>One clear plan.','Choose adult or family. Your preparation checklist stays on this device; no medical questionnaire is required.')+sec('''<div class="split"><form id="en-kit" class="form card"><fieldset><legend>Who is it for?</legend><label class="check"><input type="radio" name="kit" value="adult" checked> Adult</label><label class="check"><input type="radio" name="kit" value="family"> Family with children</label></fieldset><label class="field">Preferred format<select name="format"><option>Guide</option><option>DIY</option><option>Premium</option></select></label><p class="notice">No payment or pharmacy order is placed. Medicine purchases follow an individually agreed list.</p></form><div class="card"><h2 id="en-kit-title">Your preparation plan</h2><div id="en-kit-list"></div><p id="en-kit-progress" role="status"></p><button id="en-kit-download" class="btn primary">Download checklist ↓</button></div></div>''')
 c['assistant']=intro('AI assistant','What medicines belong at home.<br>And why.','The planned AI module would explain suggestions for review with a healthcare professional. Today’s tool prepares questions and explains why they matter; it does not use AI or prescribe medicines.')+sec('''<div class="split"><div><span class="badge">Available now: question builder</span><h2>Prepare for a useful<br>conversation with your doctor.</h2><p>Select the topics you want to discuss. There is no need to enter diagnoses, medical records or identifying details.</p><p>A future assistant should explain the purpose of each suggestion, its limitations and sources, and leave the final decision to the clinician.</p></div><form id="en-doctor" class="form card"><label class="field">For whom?<select name="who"><option>For an adult</option><option>For a family with children</option></select></label><label class="check"><input type="checkbox" name="regular"> Regularly prescribed medicines</label><label class="check"><input type="checkbox" name="allergy"> Allergies and restrictions</label><label class="check"><input type="checkbox" name="travel"> Travel preparation</label><label class="check"><input type="checkbox" name="storage"> Storage and expiry dates</label><button class="btn primary">Build my questions</button><pre id="en-doctor-result" class="english-result" aria-live="polite"></pre><button type="button" id="en-doctor-download" class="btn" hidden>Download questions ↓</button></form></div>''')+sec(cards([('Purpose','What need would an item address, and is it relevant to your household?'),('Limitations','A clinician should check age restrictions, contraindications and interactions.'),('Storage','Check the manufacturer’s requirements, expiry and shelf life after opening.')]))
 c['partners']=intro('Partners & distributors','Bring preparedness<br>to more homes.','We invite retailers, distributors and pharmacy partners to help develop SAFEBOX.')+sec(cards([('Retail partners','Explore product presentation, customer education and the appropriate sales format.'),('Distributors','Discuss regions, logistics and the steps needed to launch distribution.'),('Pharmacy networks','Explore a future route from a reviewed medicine list to a pharmacy order.')]))+sec('<div class="split"><div><h2>Let’s discuss<br>the right format.</h2><p>Tell us your region, sales channels and proposed role. Prices, margins, minimum orders and exclusivity have not been published and must be agreed separately.</p><p>The project is preparing for launch. This page is an invitation to discuss cooperation, not a confirmed commercial offer.</p></div>'+contact_form(True)+'</div>')
 c['faq']=intro('Frequently asked questions','Understand the system.<br>Know its limits.','Clear answers about the concept, preparation tools and future launch.')+sec(faq(FAQ))+resources()
 c['stories']=intro('Stories & feedback','The experiences<br>behind SAFEBOX.','Personal founder stories are separate from product reviews. Verified customer feedback will be published after testing, with permission.')+CHILD+WIFE+sec('<div class="notice">We do not publish invented testimonials or claim that these stories establish product effectiveness.</div>'+btn('Prepare your feedback','contacts.html?topic=review'))
 c['kids']=intro('Caring for children','Care begins<br>with attention.','A proposed range of play-doctor sets and a future programme to support children’s homes.')+sec(cards([('Learning through play','The idea is to help families explore care and the role of a doctor through age-appropriate play.'),('Age suitability','The concept mentions a 1+ range. Final age labelling and safety requirements must be verified before launch.'),('Separate from medicines','Play sets are toys. Children must not have free access to real medicines or medical supplies.')]))+sec(head('A future giving programme','Purchases with a wider purpose.')+'<p>We plan to allocate part of eligible sales to support children’s homes. The amount, participating products, beneficiary organisation and reporting process will be announced before the programme begins.</p><div class="notice">The programme is in development. Contributions are not currently being made under the programme described here.</div>'+btn('Discuss cooperation','contacts.html?topic=kids'))
 c['contacts']=intro('Contact','Let’s talk<br>about what matters.','Questions about the product, partnership ideas or feedback: prepare your enquiry here.')+sec('<div class="split"><div><h2>Preparing for launch.</h2><p>Public contact details, seller information and support channels will be published before sales begin.</p><p>This form prepares a local draft. It is not a medical consultation or an emergency contact service.</p>'+btn('Partner enquiries','partners.html')+'</div>'+contact_form()+'</div>')
 tabs='<nav class="resource-tabs" aria-label="Resource library">'+''.join(f'<a href="{s}.html">{t}</a>' for s,t in PAGES[12:])+'<a href="assistant.html">AI assistant</a></nav>'
 sources=[('croup','Croup in children','Symptoms, when to seek help, and a video explanation by a doctor.','NHS','https://www.nhs.uk/conditions/croup/'),('children','First aid for children','Educational resources for parents and carers.','British Red Cross','https://www.redcross.org.uk/first-aid/learn-first-aid-for-babies-and-children'),('breathing','Unresponsive but breathing','An educational first-aid video for an adult.','British Red Cross','https://www.youtube.com/watch?v=5fK2oCiz8VU'),('not-breathing','Unresponsive and not breathing','An educational first-aid video for an adult.','British Red Cross','https://www.youtube.com/watch?v=gDmy0of0XAk')]
 c['qr-library']=intro('QR library','The right resource.<br>One scan away.','Scan with your phone or open the link on this device. All listed resources are in English.')+sec(tabs+'<div class="notice">Codes lead to external NHS and British Red Cross resources. An internet connection is required. These are materials for learning in advance, not individual medical instructions.</div><div class="grid two">'+''.join(f'<article class="card qr-card"><img src="assets/qr/{key}.svg" width="168" height="168" alt="QR code for {title}"><div><span class="eyebrow">{author}</span><h2>{title}</h2><p>{desc}</p>{btn("Open resource",url)}<a class="qr-download" href="assets/qr/{key}.svg" download>Download QR for printing ↓</a></div></article>' for key,title,desc,author,url in sources)+'</div>')
 c['video-library']=intro('Video library','Watch ahead.<br>Learn the essentials.','A selection of public educational videos. Each resource names its publisher and opens on the original website.')+sec(tabs+'<div class="notice">In an emergency, seek help immediately rather than searching for a video. Emergency numbers in these materials depend on the country. Use the appropriate number for your location.</div><div class="grid">'+''.join(f'<article class="card video-card"><a class="video-cover" href="{url}"><span aria-hidden="true">▷</span><strong>{title}</strong></a><span class="eyebrow">{author}</span><h2>{title}</h2><p>{desc}</p>{btn("Watch at source",url)}</article>' for key,title,desc,author,url in [sources[0],sources[2],sources[3]])+'</div>')+sec(head('SAFEBOX videos / planned','Learn your own system.')+cards([('Organise the sections','Planned: turn an agreed list into a clearly labelled layout.'),('Review your supplies','Planned: check dates, packaging and storage requirements.'),('Introduce the system','Planned: show other adults where to find supplies and information.')]))
 c['printed-guide']=intro('Printed guide','Important information.<br>Within reach.','A paper reference alongside your kit: storage, individual instructions and useful contacts.')+sec(tabs+'''<div class="split"><div class="guide-cover"><span>SAFE<span>BOX</span></span><h2>Your home kit.<br>Organised.<br>Prepared.</h2><p>Printed guide concept</p><b>01 — Storage<br>02 — Your household list<br>03 — Review</b></div><div><span class="badge">Printed edition in development</span><h2>Buy the printed guide</h2><p>A separate paper edition is planned. Price, page count, shipping and launch date have not been confirmed.</p><button class="btn primary" disabled>Sales are not open yet</button><p class="small muted">Payment and ordering are not available.</p><h3>Planned contents</h3><ul class="points"><li>A map of your storage sections</li><li>Space for individual prescriptions and restrictions</li><li>An expiry and replenishment log</li><li>Family contacts and links to learning resources</li></ul></div></div>''')+sec('''<div class="card printable-sheet" id="guide-sample"><span class="eyebrow">Free preparation sheet / sample, not the full guide</span><h2>Start with an organised plan.</h2><p>Fill in this sheet with your family. Record medicines and instructions only as agreed with your healthcare professional.</p><h3>Where is the kit?</h3><p>________________________________________________</p><h3>Where are individual instructions kept?</h3><p>________________________________________________</p><h3>Reviewed on / next review</h3><p>________________________________________________</p><h3>Questions for the doctor</h3><p>________________________________________________</p><ul class="points"><li>Check expiry dates and storage requirements</li><li>Keep products identifiable in their original packaging</li><li>Make the location familiar to adults and inaccessible to children</li><li>Record family contacts and local emergency numbers</li></ul><button class="btn" id="print-guide" type="button">Print this sheet ↓</button></div>''')
 return c

def build_english(root):
 out=root.parent/'eng'
 out.mkdir(exist_ok=True)
 content=make_content()
 from catalog import extend_catalog
 extend_catalog(content, en=True)
 from product_slides import add_product_slides
 content['index'] = add_product_slides(content['index'], en=True)
 for slug,title in PAGES:
  nav=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if slug==s else '')+f'>{t}</a>' for s,t in [('why','Why SAFEBOX'),('how-it-works','How it works'),('products','Products'),('about','About'),('qr-library','Library'),('partners','Partners')])
  foot=''.join('<div><h3>'+label+'</h3>'+''.join(f'<a href="{s}.html">{t}</a>' for s,t in items)+'</div>' for label,items in [('System',PAGES[1:5]),('For you',[PAGES[i] for i in [5,6,8,9]]),('Together',[PAGES[i] for i in [7,10,11]]),('Library',PAGES[12:])])
  home='<link rel="stylesheet" href="../site/assets/home.css"><link rel="stylesheet" href="../site/assets/opening.css"><link rel="stylesheet" href="../site/assets/reference.css">' if slug=='index' else ''
  body=content[slug].replace('src="assets/','src="../site/assets/').replace('href="assets/','href="../site/assets/')
